//! On-device person segmentation for Background blur.
//!
//! Purpose: runs the MediaPipe selfie segmenter (landscape, 256 x 144) in safe Rust, with no
//! inference runtime and no CPU-specific code. The weights are embedded as fp16 (`weights.bin`,
//! see `MODEL.md`) and the network is the op list in `netdef.rs`, both generated by
//! `tools/selfie_weights.py`. One run takes about 3 ms on a desktop CPU.
//!
//! Invariants:
//! - [`Segmenter::run`] never allocates: every buffer is made in [`Segmenter::new`].
//! - Wrong-sized input or mask slices are ignored and the mask is left as it was.
//! - Input is planar CHW RGB in [0, 1], 3 x [`MODEL_H`] x [`MODEL_W`]. The mask is row-major,
//!   [`MODEL_H`] x [`MODEL_W`], with 255 for person and 0 for background. Values between are
//!   soft edges.
//! - The result depends only on the input and the weights, so it is the same on every machine.
//! - There is no `unsafe` code in this module or its children.

mod kernels;
mod net;
#[rustfmt::skip] // generated by tools/selfie_weights.py
mod netdef;
mod ops;
#[cfg(test)]
mod tests;

use net::Net;

/// Model input width (MediaPipe selfie segmenter, landscape variant).
pub const MODEL_W: usize = 256;
/// Model input height.
pub const MODEL_H: usize = 144;

/// The selfie segmentation network with its weights loaded.
pub struct Segmenter {
    net: Net,
    /// Pre-sigmoid network output, kept so `run` needs no allocation.
    logits: Vec<f32>,
}

impl Segmenter {
    /// Builds the network from the embedded fp16 weights. Allocates all working memory.
    pub fn new() -> Segmenter {
        Segmenter {
            net: Net::new(),
            logits: vec![0.0; MODEL_W * MODEL_H],
        }
    }

    /// Writes the person mask for `input` into `mask`. Wrong lengths leave `mask` untouched.
    pub fn run(&mut self, input: &[f32], mask: &mut [u8]) {
        if mask.len() != MODEL_W * MODEL_H || !self.forward(input) {
            return;
        }
        for (m, &l) in mask.iter_mut().zip(&self.logits) {
            // Rounded, then clamped by the `as` cast; the sigmoid is already within 0..=1.
            *m = (ops::sigmoid(l) * 255.0 + 0.5) as u8;
        }
    }

    /// Runs the network into `self.logits`. False if `input` is the wrong length.
    fn forward(&mut self, input: &[f32]) -> bool {
        if input.len() != 3 * MODEL_W * MODEL_H {
            return false;
        }
        self.net.run(input, &mut self.logits);
        true
    }

    /// The network output before the sigmoid, for the parity test.
    #[cfg(test)]
    fn logits(&mut self, input: &[f32]) -> Option<&[f32]> {
        self.forward(input).then_some(&self.logits[..])
    }
}

impl Default for Segmenter {
    fn default() -> Self {
        Self::new()
    }
}
